import { useState, useEffect } from "react";
import { API_URL } from "../config/api";
import { manejarError } from "../utils/errorHandler";
import { useNotification } from "../context/NotificationContext";
import { useConfirm } from "../context/ConfirmContext";

export function useEmpleados() {
  const { showToast } = useNotification();
  const confirm = useConfirm();

  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({
    nombre: "",
    dui: "",
    area: "",
    puesto: "",
    salario_mensual: 0,
    fecha_ingreso: ""
  });
  const [empleadoCargado, setEmpleadoCargado] = useState(false);
  const [empleadoEditandoId, setEmpleadoEditandoId] = useState(null);
  const [filtroEmpleados, setFiltroEmpleados] = useState("");

  // Cargar empleados al iniciar
  useEffect(() => {
    const cargarEmpleados = async () => {
      try {
        const res = await fetch(`${API_URL}/empleado`);
        if (res.ok) {
          const data = await res.json();
          setEmpleados(data);
        }
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };
    cargarEmpleados();
  }, []);

  const crearEmpleado = async (e) => {
    e.preventDefault();
    const duiRegex = /^\d{8}-\d{1}$/;
    if (!duiRegex.test(nuevoEmpleado.dui)) {
      showToast("El DUI debe tener el formato ########-# (8 dígitos, guion y 1 dígito)", "error");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/empleado/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados([...empleados, data]);
        limpiarFormularioEmpleado();
        showToast("Empleado creado exitosamente", "success");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        showToast(mensaje, "error");
      }
    } catch (error) {
      console.error("Error al crear empleado:", error);
      showToast("Error de conexión con el backend", "error");
    }
  };

  const actualizarEmpleado = async (e) => {
    e.preventDefault();
    const duiRegex = /^\d{8}-\d{1}$/;
    if (!duiRegex.test(nuevoEmpleado.dui)) {
      showToast("El DUI debe tener el formato ########-# (8 dígitos, guion y 1 dígito)", "error");
      return;
    }
    try {
      const res = await fetch(`${API_URL}/empleado/${empleadoEditandoId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados(empleados.map(emp => emp.id === data.id ? data : emp));
        limpiarFormularioEmpleado();
        showToast("Empleado actualizado exitosamente", "success");
      } else {
        const error = await res.json();
        const mensaje = manejarError(error);
        showToast(mensaje, "error");
      }
    } catch (error) {
      console.error("Error al actualizar empleado:", error);
      showToast("Error de conexión con el backend", "error");
    }
  };

  const eliminarEmpleado = async (id) => {
    const confirmado = await confirm("¿Seguro que deseas eliminar este empleado?");
    if (!confirmado) return;
    try {
      const res = await fetch(`${API_URL}/empleado/${id}`, { method: "DELETE" });
      if (res.ok) {
        setEmpleados(empleados.filter(emp => emp.id !== id));
        showToast("Empleado eliminado", "success");
      } else {
        showToast("Error al eliminar, verificar si tiene planillas asociadas", "error");
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
    }
  };

  const cargarEmpleado = (emp) => {
    setNuevoEmpleado({
      nombre: emp.nombre || "",
      dui: emp.dui || "",
      area: emp.area || "",
      puesto: emp.puesto || "",
      salario_mensual: emp.salario_mensual || 0,
      fecha_ingreso: emp.fecha_ingreso || ""
    });
    setEmpleadoCargado(true);
    setEmpleadoEditandoId(emp.id);
  };

  const limpiarFormularioEmpleado = () => {
    setNuevoEmpleado({ nombre: "", dui: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: "" });
    setEmpleadoCargado(false);
    setEmpleadoEditandoId(null);
  };

  return {
    empleados,
    nuevoEmpleado,
    setNuevoEmpleado,
    empleadoCargado,
    empleadoEditandoId,
    filtroEmpleados,
    setFiltroEmpleados,
    crearEmpleado,
    actualizarEmpleado,
    eliminarEmpleado,
    cargarEmpleado,
    limpiarFormularioEmpleado
  };
}
